export const SQL = {
  "main.sql": "/*\n  Q-WorkDone - shared tables (PostgreSQL 14+), in the \"public\" schema.\n\n  The Client ID entered at sign-in is looked up in Clients to find that company's schema.\n  SchemaVersions records which version of client.sql each schema has, so the app upgrades\n  schemas only when it is newer. Idempotent; the app runs it at start-up.\n*/\n\n-- Case-insensitive text for usernames, e-mails and codes (a trusted extension: no superuser needed)\nCREATE EXTENSION IF NOT EXISTS citext;\n\nCREATE TABLE IF NOT EXISTS public.Clients (\n    ClientId     varchar(30)  PRIMARY KEY,           -- stored upper-case\n    CompanyName  varchar(150) NOT NULL,\n    SchemaName   varchar(63)  NOT NULL UNIQUE,       -- schema holding the company's tables, e.g. wd_acme\n    IsActive     boolean      NOT NULL DEFAULT true,\n    CreatedAt    timestamptz  NOT NULL DEFAULT now(),\n    UpdatedAt    timestamptz  NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS public.SchemaVersions (\n    SchemaName  varchar(63) PRIMARY KEY,\n    Version     integer     NOT NULL,\n    UpdatedAt   timestamptz NOT NULL DEFAULT now()\n);\n\n-- Sign-in attempts with an unknown Client ID are recorded here (they belong to no company)\nCREATE TABLE IF NOT EXISTS public.SecurityEvents (\n    EventId    bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n    EventType  varchar(50)  NOT NULL,\n    UserId     integer,\n    Username   varchar(50),\n    IpAddress  varchar(64),\n    Details    varchar(500),\n    CreatedAt  timestamptz  NOT NULL DEFAULT now()\n);\n",
  "client.sql": "/*\n  Q-WorkDone - tables of one client company (PostgreSQL 14+).\n\n  Every client company has its own schema (e.g. wd_acme). The app runs this script with \"dbo.\"\n  replaced by that schema, when the company is created and whenever the app starts with a newer\n  schema version. It is idempotent: safe to run again at any time.\n\n  Conventions\n  - Timestamps are timestamptz (absolute instants); dates the user picks are date.\n  - Usernames, e-mails and codes are citext: unique and matched without regard to case.\n  - Records referenced by work history are never deleted, only deactivated.\n*/\n\n/* ---------- Employees ---------- */\nCREATE TABLE IF NOT EXISTS dbo.Employees (\n    EmployeeId    integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n    EmployeeCode  citext       NOT NULL UNIQUE,\n    EmployeeName  varchar(100) NOT NULL,\n    Department    varchar(100),\n    Phone         varchar(30),\n    Email         citext,\n    JoiningDate   date,\n    IsActive      boolean      NOT NULL DEFAULT true,\n    CreatedAt     timestamptz  NOT NULL DEFAULT now(),\n    UpdatedAt     timestamptz  NOT NULL DEFAULT now()\n);\n\n/* ---------- Users ---------- */\nCREATE TABLE IF NOT EXISTS dbo.Users (\n    UserId              integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n    ClientId            varchar(30),                     -- Client ID of the company (as in public.Clients)\n    Username            citext       NOT NULL UNIQUE,\n    Email               citext,                          -- optional; can be used instead of the username to sign in\n    PasswordHash        varchar(255) NOT NULL,\n    Role                varchar(20)  NOT NULL CHECK (Role IN ('Admin', 'Manager', 'Employee')),\n    EmployeeId          integer      REFERENCES dbo.Employees (EmployeeId),\n    MustChangePassword  boolean      NOT NULL DEFAULT true,\n    IsActive            boolean      NOT NULL DEFAULT true,\n    LastLoginAt         timestamptz,\n    CreatedAt           timestamptz  NOT NULL DEFAULT now(),\n    UpdatedAt           timestamptz  NOT NULL DEFAULT now(),\n    -- Employee accounts must be linked to an employee record\n    CONSTRAINT ck_users_employee_link CHECK (Role <> 'Employee' OR EmployeeId IS NOT NULL)\n);\nCREATE UNIQUE INDEX IF NOT EXISTS ux_users_employee ON dbo.Users (EmployeeId) WHERE EmployeeId IS NOT NULL;\nCREATE UNIQUE INDEX IF NOT EXISTS ux_users_email ON dbo.Users (Email) WHERE Email IS NOT NULL;\n\n/* ---------- Application settings ---------- */\nCREATE TABLE IF NOT EXISTS dbo.AppSettings (\n    SettingKey    varchar(50)  PRIMARY KEY,\n    SettingValue  varchar(500),\n    UpdatedAt     timestamptz  NOT NULL DEFAULT now()\n);\n\n/* ---------- Product groups & products ---------- */\nCREATE TABLE IF NOT EXISTS dbo.ProductGroups (\n    ProductGroupId  integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n    GroupCode       citext       NOT NULL UNIQUE,\n    GroupName       varchar(100) NOT NULL,\n    Description     varchar(500),\n    IsActive        boolean      NOT NULL DEFAULT true,\n    CreatedAt       timestamptz  NOT NULL DEFAULT now(),\n    UpdatedAt       timestamptz  NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS dbo.Products (\n    ProductId       integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n    ProductCode     citext       NOT NULL UNIQUE,\n    ProductName     varchar(150) NOT NULL,\n    ProductGroupId  integer      NOT NULL REFERENCES dbo.ProductGroups (ProductGroupId),\n    Description     varchar(500),\n    IsActive        boolean      NOT NULL DEFAULT true,\n    CreatedAt       timestamptz  NOT NULL DEFAULT now(),\n    UpdatedAt       timestamptz  NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS ix_products_group ON dbo.Products (ProductGroupId);\n\n/* ---------- Repeating work (templates) ---------- */\n/* NextDueDate is the due date of the next item to create; the item is created LeadDays before it\n   (its start date) by the background job. AnchorDay keeps \"the 31st\" from drifting after February. */\nCREATE TABLE IF NOT EXISTS dbo.RecurringWork (\n    RecurringId       integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n    Title             varchar(200) NOT NULL,\n    Description       text,\n    ProductGroupId    integer      REFERENCES dbo.ProductGroups (ProductGroupId),\n    ProductId         integer      REFERENCES dbo.Products (ProductId),\n    Priority          varchar(10)  NOT NULL DEFAULT 'Medium' CHECK (Priority IN ('Low', 'Medium', 'High', 'Urgent')),\n    Frequency         varchar(10)  NOT NULL CHECK (Frequency IN ('Weekly', 'Monthly', 'Quarterly', 'Yearly')),\n    AnchorDay         smallint     NOT NULL,\n    NextDueDate       date         NOT NULL,\n    LeadDays          smallint     NOT NULL DEFAULT 7 CHECK (LeadDays BETWEEN 0 AND 90),\n    EndDate           date,\n    IsActive          boolean      NOT NULL DEFAULT true,\n    CreatedByUserId   integer      NOT NULL REFERENCES dbo.Users (UserId),\n    CreatedAt         timestamptz  NOT NULL DEFAULT now(),\n    UpdatedAt         timestamptz  NOT NULL DEFAULT now(),\n    LastCreatedAt     timestamptz\n);\nCREATE INDEX IF NOT EXISTS ix_recurringwork_next ON dbo.RecurringWork (IsActive, NextDueDate);\n\nCREATE TABLE IF NOT EXISTS dbo.RecurringWorkAssignees (\n    RecurringId  integer NOT NULL REFERENCES dbo.RecurringWork (RecurringId),\n    EmployeeId   integer NOT NULL REFERENCES dbo.Employees (EmployeeId),\n    PRIMARY KEY (RecurringId, EmployeeId)\n);\n\n/* ---------- Work items ---------- */\n/* RowVer is the optimistic-concurrency token: every update gets a new value (trigger below), so a\n   second save based on stale data is rejected with \"changed by someone else\". */\nCREATE SEQUENCE IF NOT EXISTS dbo.rowver_seq;\n\nCREATE TABLE IF NOT EXISTS dbo.WorkItems (\n    WorkId           integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n    -- Human-readable number derived from the id, e.g. WD-000042\n    WorkNo           varchar(20) GENERATED ALWAYS AS ('WD-' || lpad(WorkId::text, 6, '0')) STORED,\n    Title            varchar(200) NOT NULL,\n    Description      text,\n    ProductGroupId   integer      REFERENCES dbo.ProductGroups (ProductGroupId),\n    ProductId        integer      REFERENCES dbo.Products (ProductId),\n    Priority         varchar(10)  NOT NULL DEFAULT 'Medium' CHECK (Priority IN ('Low', 'Medium', 'High', 'Urgent')),\n    Status           varchar(20)  NOT NULL DEFAULT 'Pending'\n                                  CHECK (Status IN ('Pending', 'In Progress', 'On Hold', 'Completed', 'Closed', 'Reopened')),\n    StartDate        date,\n    DueDate          date,\n    CreatedByUserId  integer      NOT NULL REFERENCES dbo.Users (UserId),\n    CreatedAt        timestamptz  NOT NULL DEFAULT now(),\n    UpdatedAt        timestamptz  NOT NULL DEFAULT now(),\n    ClosedAt         timestamptz,\n    RecurringId      integer      REFERENCES dbo.RecurringWork (RecurringId),\n    RowVer           bigint       NOT NULL DEFAULT nextval('dbo.rowver_seq'),\n    CONSTRAINT ck_workitems_dates CHECK (StartDate IS NULL OR DueDate IS NULL OR DueDate >= StartDate)\n);\nCREATE UNIQUE INDEX IF NOT EXISTS ux_workitems_workno ON dbo.WorkItems (WorkNo);\nCREATE INDEX IF NOT EXISTS ix_workitems_status_due ON dbo.WorkItems (Status, DueDate);\nCREATE INDEX IF NOT EXISTS ix_workitems_due ON dbo.WorkItems (DueDate);\nCREATE INDEX IF NOT EXISTS ix_workitems_created ON dbo.WorkItems (CreatedAt);\nCREATE INDEX IF NOT EXISTS ix_workitems_updated ON dbo.WorkItems (UpdatedAt);\nCREATE INDEX IF NOT EXISTS ix_workitems_product ON dbo.WorkItems (ProductId);\nCREATE INDEX IF NOT EXISTS ix_workitems_group ON dbo.WorkItems (ProductGroupId);\nCREATE INDEX IF NOT EXISTS ix_workitems_recurring ON dbo.WorkItems (RecurringId) WHERE RecurringId IS NOT NULL;\n\nCREATE OR REPLACE FUNCTION dbo.bump_rowver() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n    NEW.RowVer := nextval('dbo.rowver_seq');\n    RETURN NEW;\nEND $$;\nCREATE OR REPLACE TRIGGER trg_workitems_rowver BEFORE UPDATE ON dbo.WorkItems\n    FOR EACH ROW EXECUTE FUNCTION dbo.bump_rowver();\n\n/* ---------- Work assignments (one work item -> many employees) ---------- */\nCREATE TABLE IF NOT EXISTS dbo.WorkAssignments (\n    AssignmentId        integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n    WorkId              integer     NOT NULL REFERENCES dbo.WorkItems (WorkId),\n    EmployeeId          integer     NOT NULL REFERENCES dbo.Employees (EmployeeId),\n    AssignedByUserId    integer     NOT NULL REFERENCES dbo.Users (UserId),\n    AssignedAt          timestamptz NOT NULL DEFAULT now(),\n    IsActive            boolean     NOT NULL DEFAULT true,\n    UnassignedAt        timestamptz,\n    UnassignedByUserId  integer     REFERENCES dbo.Users (UserId)\n);\n-- The same employee can be actively assigned to a work item only once\nCREATE UNIQUE INDEX IF NOT EXISTS ux_workassignments_active ON dbo.WorkAssignments (WorkId, EmployeeId) WHERE IsActive;\nCREATE INDEX IF NOT EXISTS ix_workassignments_employee ON dbo.WorkAssignments (EmployeeId, IsActive) INCLUDE (WorkId);\n\n/* ---------- Work status history / activity log ---------- */\nCREATE TABLE IF NOT EXISTS dbo.WorkStatusHistory (\n    HistoryId        bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n    WorkId           integer      NOT NULL REFERENCES dbo.WorkItems (WorkId),\n    EntryType        varchar(20)  NOT NULL DEFAULT 'StatusChange'\n                                  CHECK (EntryType IN ('Created', 'StatusChange', 'Note', 'Assignment', 'Edit', 'Attachment')),\n    OldStatus        varchar(20),\n    NewStatus        varchar(20)  NOT NULL,\n    ChangedByUserId  integer      NOT NULL REFERENCES dbo.Users (UserId),\n    Notes            varchar(2000),\n    ChangedAt        timestamptz  NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS ix_workstatushistory_work ON dbo.WorkStatusHistory (WorkId, ChangedAt);\nCREATE INDEX IF NOT EXISTS ix_workstatushistory_changed ON dbo.WorkStatusHistory (ChangedAt) INCLUDE (WorkId, EntryType, NewStatus);\n\n/* ---------- Files attached to work items ---------- */\n/* Kept in the company's own schema. Deleting a file erases its content but keeps the row and a\n   history entry, so the activity log stays complete. */\nCREATE TABLE IF NOT EXISTS dbo.WorkAttachments (\n    AttachmentId      integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n    WorkId            integer      NOT NULL REFERENCES dbo.WorkItems (WorkId),\n    FileName          varchar(255) NOT NULL,\n    ContentType       varchar(100) NOT NULL,\n    SizeBytes         integer      NOT NULL,\n    Content           bytea,\n    UploadedByUserId  integer      NOT NULL REFERENCES dbo.Users (UserId),\n    CreatedAt         timestamptz  NOT NULL DEFAULT now(),\n    DeletedAt         timestamptz,\n    DeletedByUserId   integer      REFERENCES dbo.Users (UserId)\n);\nCREATE INDEX IF NOT EXISTS ix_workattachments_work ON dbo.WorkAttachments (WorkId) INCLUDE (FileName, SizeBytes, DeletedAt);\n\n/* ---------- Sessions & security log ---------- */\nCREATE TABLE IF NOT EXISTS dbo.Sessions (\n    SessionId   bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n    TokenHash   char(64)     NOT NULL UNIQUE,  -- SHA-256 of the cookie token; the raw token is never stored\n    UserId      integer      NOT NULL REFERENCES dbo.Users (UserId),\n    CreatedAt   timestamptz  NOT NULL DEFAULT now(),\n    LastSeenAt  timestamptz  NOT NULL DEFAULT now(),\n    ExpiresAt   timestamptz  NOT NULL,\n    RevokedAt   timestamptz,\n    IpAddress   varchar(64),\n    UserAgent   varchar(300)\n);\nCREATE INDEX IF NOT EXISTS ix_sessions_user ON dbo.Sessions (UserId) INCLUDE (RevokedAt, ExpiresAt);\n\nCREATE TABLE IF NOT EXISTS dbo.SecurityEvents (\n    EventId    bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n    EventType  varchar(50)  NOT NULL,\n    UserId     integer,\n    Username   varchar(50),\n    IpAddress  varchar(64),\n    Details    varchar(500),\n    CreatedAt  timestamptz  NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS ix_securityevents_created ON dbo.SecurityEvents (CreatedAt);\n\n/* ---------- Chat ---------- */\n/* One \"Company\" conversation (everyone in this client), one \"Direct\" conversation per pair of users,\n   and any number of named \"Group\" conversations. */\nCREATE TABLE IF NOT EXISTS dbo.ChatConversations (\n    ConversationId   integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n    Kind             varchar(10)  NOT NULL CHECK (Kind IN ('Company', 'Direct', 'Group')),\n    Title            varchar(100),          -- group name\n    -- Direct chats: \"<lower UserId>:<higher UserId>\"; the company chat: \"*\"\n    DirectKey        varchar(30),\n    CreatedByUserId  integer      REFERENCES dbo.Users (UserId),\n    CreatedAt        timestamptz  NOT NULL DEFAULT now(),\n    LastMessageAt    timestamptz\n);\nCREATE UNIQUE INDEX IF NOT EXISTS ux_chatconversations_directkey ON dbo.ChatConversations (DirectKey) WHERE DirectKey IS NOT NULL;\n\nCREATE TABLE IF NOT EXISTS dbo.ChatMembers (\n    ConversationId     integer     NOT NULL REFERENCES dbo.ChatConversations (ConversationId),\n    UserId             integer     NOT NULL REFERENCES dbo.Users (UserId),\n    -- Messages up to this id have been read by the user (drives unread counts)\n    LastReadMessageId  bigint      NOT NULL DEFAULT 0,\n    JoinedAt           timestamptz NOT NULL DEFAULT now(),\n    PRIMARY KEY (ConversationId, UserId)\n);\nCREATE INDEX IF NOT EXISTS ix_chatmembers_user ON dbo.ChatMembers (UserId);\n\nCREATE TABLE IF NOT EXISTS dbo.ChatMessages (\n    MessageId       bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n    ConversationId  integer       NOT NULL REFERENCES dbo.ChatConversations (ConversationId),\n    SenderUserId    integer       NOT NULL REFERENCES dbo.Users (UserId),\n    Body            varchar(2000) NOT NULL,\n    CreatedAt       timestamptz   NOT NULL DEFAULT now(),\n    EditedAt        timestamptz,\n    DeletedAt       timestamptz\n);\nCREATE INDEX IF NOT EXISTS ix_chatmessages_conversation ON dbo.ChatMessages (ConversationId, MessageId) INCLUDE (SenderUserId, CreatedAt);\n\n/* Files sent in chat (one per message). Content is erased when the message is deleted. */\nCREATE TABLE IF NOT EXISTS dbo.ChatAttachments (\n    AttachmentId  integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n    MessageId     bigint        NOT NULL UNIQUE REFERENCES dbo.ChatMessages (MessageId),\n    FileName      varchar(255)  NOT NULL,\n    ContentType   varchar(100)  NOT NULL,\n    SizeBytes     integer       NOT NULL,\n    Content       bytea,\n    CreatedAt     timestamptz   NOT NULL DEFAULT now()\n);\n\n/* ---------- In-app notifications ---------- */\nCREATE TABLE IF NOT EXISTS dbo.Notifications (\n    NotificationId  bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n    UserId          integer      NOT NULL REFERENCES dbo.Users (UserId),\n    Kind            varchar(20)  NOT NULL\n                                 CHECK (Kind IN ('Assigned', 'Status', 'Note', 'Mention', 'Attachment', 'DueToday', 'Overdue', 'Created')),\n    WorkId          integer      REFERENCES dbo.WorkItems (WorkId),\n    ActorUserId     integer      REFERENCES dbo.Users (UserId),\n    Message         varchar(400) NOT NULL,\n    CreatedAt       timestamptz  NOT NULL DEFAULT now(),\n    ReadAt          timestamptz\n);\nCREATE INDEX IF NOT EXISTS ix_notifications_user ON dbo.Notifications (UserId, NotificationId DESC) INCLUDE (ReadAt);\nCREATE INDEX IF NOT EXISTS ix_notifications_work ON dbo.Notifications (WorkId, Kind, UserId) INCLUDE (CreatedAt);\n\n/* ---------- Live events (serverless hosting only) ---------- */\n/* On a serverless host each request may run in a different short-lived instance, so live chat and\n   notification events are written here and each open tab's event stream picks up the new rows.\n   Rows are only needed for a minute or two; the daily job deletes those older than a day. */\nCREATE TABLE IF NOT EXISTS dbo.LiveEvents (\n    EventId    bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n    UserIds    integer[],                -- recipients; NULL = everyone in the company\n    EventType  varchar(30)  NOT NULL,\n    Payload    jsonb        NOT NULL,\n    CreatedAt  timestamptz  NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS ix_liveevents_created ON dbo.LiveEvents (CreatedAt);\n",
  "seed.sql": "/*\n  Q-WorkDone - DEVELOPMENT sample data for one company (\"dbo.\" = its schema).\n  Master data only; no user accounts. Do NOT load this into a real company.\n*/\nINSERT INTO dbo.Employees (EmployeeCode, EmployeeName, Department, Phone, Email, JoiningDate) VALUES\n    ('EMP001', 'Amit Sharma', 'Development', '9800000001', 'amit@example.local',  '2022-04-01'),\n    ('EMP002', 'Priya Verma', 'Development', '9800000002', 'priya@example.local', '2023-01-16'),\n    ('EMP003', 'Rahul Gupta', 'Support',     '9800000003', 'rahul@example.local', '2021-07-12'),\n    ('EMP004', 'Neha Singh',  'Testing',     '9800000004', 'neha@example.local',  '2024-02-05'),\n    ('EMP005', 'Vikas Kumar', 'Support',     '9800000005', 'vikas@example.local', '2020-11-23')\nON CONFLICT (EmployeeCode) DO NOTHING;\n\nINSERT INTO dbo.ProductGroups (GroupCode, GroupName, Description) VALUES\n    ('ACC', 'Accounting Software', 'Accounting and billing products'),\n    ('INV', 'Inventory',           'Stock and warehouse products'),\n    ('HR',  'HR & Payroll',        'Human resources and payroll products'),\n    ('WEB', 'Web Services',        'Websites and hosted services')\nON CONFLICT (GroupCode) DO NOTHING;\n\nINSERT INTO dbo.Products (ProductCode, ProductName, ProductGroupId, Description)\nSELECT s.ProductCode, s.ProductName, g.ProductGroupId, s.Description\nFROM (VALUES\n    ('ACC-BILL', 'Billing Pro',       'ACC', 'GST billing application'),\n    ('ACC-LEDG', 'Ledger Manager',    'ACC', 'Accounts ledger'),\n    ('INV-STK',  'Stock Tracker',     'INV', 'Inventory management'),\n    ('INV-WMS',  'Warehouse Manager', 'INV', 'Multi-location warehouse'),\n    ('HR-PAY',   'Payroll Plus',      'HR',  'Payroll processing'),\n    ('HR-ATT',   'Attendance System', 'HR',  'Biometric attendance'),\n    ('WEB-SITE', 'Company Website',   'WEB', 'Corporate websites'),\n    ('WEB-HOST', 'Hosting & Domains', 'WEB', 'Hosting support')\n) AS s (ProductCode, ProductName, GroupCode, Description)\nJOIN dbo.ProductGroups g ON g.GroupCode = s.GroupCode\nON CONFLICT (ProductCode) DO NOTHING;\n",
} as const;
